const msg = $json.message ?? $json;
const chat = msg.chat ?? {};
const from = msg.from ?? {};
const text = typeof msg.text === 'string' ? msg.text : '';
const name = [from.first_name, from.last_name].filter(Boolean).join(' ') ||
  (chat.username ? '@' + chat.username : null);
return [{
  json: {
    whatsapp_id: 'tg:' + chat.id,
    chat_id: String(chat.id),
    name,
    text,
    is_text: text.length > 0,
  }
}];

const booked = [];
for (const item of $('Load Booked Slots').all()) {
  if (item.json && item.json.trial_datetime) booked.push(item.json);
}
return [{ json: { booked_slots: booked, started_at: new Date().toISOString() } }];

